import { z } from 'zod'
import { nativePreparationPinSchema } from './native-task-preparation'
import { cutoverCommandSchema, cutoverManifestSchema } from './team-cutover'
import { teamDigestSchema, teamIdSchema } from './team-platform'

const stage = cutoverCommandSchema.options[0]
export const nativeWorkflowCutoverPreviewRequestSchema = z.object({ operation: z.literal('preview'), pin: nativePreparationPinSchema, command: stage }).strict()
/** Only source/review pins cross this boundary; generated bytes and digests belong to the native owner. */
export const nativeWorkflowCutoverProposeRequestSchema = z.object({ operation: z.literal('propose'), pin: nativePreparationPinSchema,
  command: stage.omit({ manifest: true, manifestDigest: true }),
  manifest: z.object({ importId: cutoverManifestSchema.shape.importId, importManifestDigest: cutoverManifestSchema.shape.importManifestDigest,
    tasks: cutoverManifestSchema.shape.tasks, conversions: cutoverManifestSchema.shape.conversions }).strict()
}).strict()
/** The physical root and native owner are supplied exclusively by the authenticated dispatcher. */
export const nativeWorkflowCutoverRequestSchema = z.discriminatedUnion('operation', [
  nativeWorkflowCutoverPreviewRequestSchema,
  nativeWorkflowCutoverProposeRequestSchema,
  z.object({ operation: z.literal('apply'), operationId: teamIdSchema, previewDigest: teamDigestSchema }).strict(),
  z.object({ operation: z.literal('recover'), operationId: teamIdSchema }).strict(),
  z.object({ operation: z.literal('suspend'), operationId: teamIdSchema }).strict(),
  z.object({ operation: z.literal('rollback'), operationId: teamIdSchema }).strict(),
  z.object({ operation: z.literal('inspect'), operationId: teamIdSchema }).strict()
])
export type NativeWorkflowCutoverRequest = z.infer<typeof nativeWorkflowCutoverRequestSchema>
const enforcement = z.object({ scope: z.literal('platform-task-boundaries'), gates: z.array(z.enum(['native-prepare-verify', 'current-handler-single-writer-adopted-input', 'fixed-artifact-delivery', 'configured-database-jira-transition'])), editorHookRegistration: z.literal('unverified') }).strict()
export const nativeWorkflowCutoverProposalSchema = z.object({ preview: nativeWorkflowCutoverPreviewRequestSchema,
  blockers: z.array(z.string().max(500)).max(4000), ready: z.boolean(), enforcement }).strict()
export const nativeWorkflowCutoverPreviewSchema = z.object({ operationId: teamIdSchema, previewDigest: teamDigestSchema,
  manifest: cutoverManifestSchema, blockers: z.array(z.string().max(500)).max(4000), ready: z.boolean(), enforcement }).strict()
